// Prepare optional magicfile path; may be NULL or a filename. We choose a filename to satisfy the contract.
const char *magicfile = FUZZ_PARAM_FILENAME();
// Flags are unspecified; keep within a small range
int flags = (int)(*FUZZ_PARAM(unsigned int) & 0xFFFF);
// Query path; caller must treat as read-only; NULL is allowed (do not assert)
const char *path = magic_getpath(magicfile, flags);
(void)path; // unused when NULL or non-NULL; we don't free it

// Obtain library version; no constraints to enforce
int v = magic_version();
(void)v;

// Generate a bounded flags bitmask (MAGIC_* are bitflags; we keep to a small range)
int flags = (int)(*FUZZ_PARAM(unsigned int) & 0xFFFF);
// Create an API handle and wrap it in a pool-managed wrapper pointer (magic_t *)
magic_t handle = magic_open(flags);
if (!handle) { FUZZ_BAIL(); }
magic_t *ms = (magic_t *)malloc(sizeof(magic_t));
if (!ms) { FUZZ_BAIL(); }
*ms = handle;
// Track lifetime and flags on the wrapper pointer object
FUZZ_SET_ATTR_INT(ms, "open", 1);
FUZZ_SET_ATTR_INT(ms, "flags", flags);
// ms is the persistent wrapper returned as output

// Enforce that this handle was created by magic_open and is currently open
if (!ms) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(ms, "open")) { FUZZ_BAIL(); }
// Close the underlying API handle and invalidate
magic_close(*ms);
FUZZ_SET_ATTR_INT(ms, "open", 0);
// Free the wrapper storage and drop from pool by not returning it
free(ms);
// No outputs returned; object is destroyed

// Validate handle lifetime (wrapper must be marked open)
